/* -- Mutex and Lock Guard -- */

std::mutex mtx;
int shared_counter = 0;

void safe_increment() {
    // RAII style locking (ensures unlock on exit/exception)
    std::lock_guard<std::mutex> lock(mtx);
    shared_counter++;
}

/* -- Atomic Operations (Lock-Free) -- */

std::atomic<int> counter{0};
std::atomic<bool> flag{false};

void update_status() {
    counter.fetch_add(1); // Atomic increment
    bool expected = false;
    // CAS (Compare and Swap) operation
    flag.compare_exchange_strong(expected, true);
}

/* -- Condition Variable (Signaling and Waiting) -- */

std::mutex m;
std::condition_variable cv;
bool data_ready = false;

void consumer_wait() {
    std::unique_lock<std::mutex> lock(m);
    // Wait releases lock, reacquires when notified & predicate is true
    cv.wait(lock, []{ return data_ready; });
}

void producer_signal() {
    {
        std::lock_guard<std::mutex> lock(m);
        data_ready = true;
    } // Lock released before notifying
    cv.notify_one();
}

/* -- Future and Promise (Async Result Retrieval) -- */

int calculate() { return 42; }

std::promise<int> p;
std::future<int> f = p.get_future();

std::thread t([&p] {
    p.set_value(calculate());
});

// Blocks until the promise sets the value
int result = f.get();

t.join();
